('4', '1', 'admin_settings', '{\"admin_password\":\"admin\"}'),
('5', '0', 'product_setting', '{\"authentication_mark\":[{\"url\":\"admin\\/20241204\\/95d573c6faa18f16e9292dc67890b0d0.png\",\"name\":\"CCC\"},{\"url\":\"admin\\/20241204\\/b466eef6ed5d62d46e59c6ac814433cc.png\",\"name\":\"CE\"},{\"url\":\"admin\\/20250107\\/eabdda3590ad3f0a7d9dc4a0d69842bf.png\",\"name\":\"ABS\"},{\"url\":\"admin\\/20250107\\/38d5193575b7383b2da204772037f7d4.png\",\"name\":\"BV\"},{\"url\":\"admin\\/20250107\\/17869a11265bf6d338c93f62d4c11143.png\",\"name\":\"CCS\"}],\"sling_available\":[{\"url\":\"admin\\/20241204\\/cc27dedaa632ef457d8916089befaedd.png\",\"name\":\"Lifting hook\"},{\"url\":\"admin\\/20241204\\/e742342a00f32e5c7716c8d33bcbfc51.png\",\"name\":\"Grab bucket\"},{\"url\":\"admin\\/20241204\\/bf01c9a481d300c38d01cea786447f25.png\",\"name\":\"Magnetic chuck\"},{\"url\":\"admin\\/20241204\\/5259b3c1b084d16a43a1266cee49af3e.png\",\"name\":\"Container spreader\"},{\"url\":\"admin\\/20241204\\/f7a37362530fa348096503b9634bdc29.png\",\"name\":\"Hanging beam\"}],\"sling_available_active\":[{\"url\":\"admin\\/20241204\\/e88eedef80dd3cc6ebed93e70768c694.png\",\"name\":\"Lifting hook\"},{\"url\":\"admin\\/20241204\\/37ec8db350bca9439ecca878186aad97.png\",\"name\":\"Grab bucket\"},{\"url\":\"admin\\/20241204\\/519cefa18c098afcac9de9bd00f2ddce.png\",\"name\":\"Magnetic chuck\"},{\"url\":\"admin\\/20241204\\/ab67224b8a7d6426f00e6e208cac9f85.png\",\"name\":\"Container spreader\"},{\"url\":\"admin\\/20241204\\/03c5d876b5fc25c4ab4d390d0609220d.png\",\"name\":\"Hanging beam\"}],\"operating_voltage\":[\"115V\",\"220V\",\"230V\",\"380V\",\"460V\"],\"operating_hertz\":[\"50Hz\",\"60Hz\"],\"job_level\":[\"A4\",\"A5\",\"A6\"],\"lifting_capacity\":[\"0.2t\",\"0.5t\",\"1t\",\"2t\",\"5t\",\"10t\",\"20t\",\"50t\",\"100t\",\"150t\",\"200t\"]}'),
('6', '1', 'upload_setting', '{\"max_files\":\"20\",\"chunk_size\":\"512\",\"file_types\":{\"image\":{\"upload_max_filesize\":\"10240\",\"extensions\":\"jpg,jpeg,png,gif,bmp4,webp,avif\"},\"video\":{\"upload_max_filesize\":\"10240\",\"extensions\":\"mp4,avi,wmv,rm,rmvb,mkv\"},\"audio\":{\"upload_max_filesize\":\"10240\",\"extensions\":\"mp3,wma,wav\"},\"file\":{\"upload_max_filesize\":\"10240\",\"extensions\":\"txt,pdf,doc,docx,xls,xlsx,ppt,pptx,zip,rar\"}}}'),
('7', '0', 'index_setting', '{\"about_description\":\"Founded in 2005 and headquartered in Xinxiang, Henan Province, China, Xinxiang Nucleon (Xinxiang) Crane Co., Ltd. is a leading manufacturer specializing in the research, development, production, and sales of overhead cranes, gantry cranes, electric hoists, jib cranes and port cranes etc.. Nucleon has a registered capital of 80 million US dollars, covering an area of 430000 square meters, and owns more than 1500 employees. The company has equipped over 3000 sets of production and testing equipment, providing support for the research and development of high-quality crane equipment. The leading products have been widely used in pillar industries of the national economy such as metallurgy, energy and power, petrochemicals, railways, and aviation, and exported to various parts of the world.\",\"engineering\":[{\"engineering_name\":\"Million\",\"engineering_desc\":\"Nucleon has a registered capital of 80 million US dollars\",\"engineering_num\":\"80\"},{\"engineering_name\":\"m²\",\"engineering_desc\":\"Nucleon covering an area of 430000 square meters\",\"engineering_num\":\"430000\"},{\"engineering_name\":\"Employees\",\"engineering_desc\":\"Nucleon owns more than 1500 employees.\",\"engineering_num\":\"1500\"},{\"engineering_name\":\"Sets\",\"engineering_desc\":\"Nucleon has equipped over 3000 sets of production and testing equipment\",\"engineering_num\":\"3000\"}],\"about_img\":\"admin\\/20260527\\/6e1caa71d0aec007314dc24b595d396f.png\",\"about_bg_img\":\"admin\\/20260527\\/6e1caa71d0aec007314dc24b595d396f.png\",\"choose_bg_img\":\"admin\\/20260529\\/d2f02e991ee7ff7e96ee20b6b2a8d41d.webp\",\"faq_bg_img\":\"admin\\/20260526\\/839b1126fe8ff2af2aa837214d682512.webp\",\"about_right_bg_img\":\"admin\\/20260527\\/31951f09d3f519ef04f57a08b5390f1c.png\",\"choose_description\":\"Nucleon Has Become The Most Trusted Partner For Over 500 Industry Professionals In The Industrial Crane Sector Across Six Continents\",\"choose\":[{\"choose_name\":\"Safety First\",\"choose_desc\":\"All cranes meet ANSI\\/ASME &amp; CE standards, with overload protection and fail-safe design.\",\"choose_image\":\"admin\\/20260527\\/68aa6c742a2d455d1408cde608051841.webp\",\"choose_image_active\":\"admin\\/20260527\\/68aa6c742a2d455d1408cde608051841.webp\"},{\"choose_name\":\"Custom Engineering\",\"choose_desc\":\"Tailored to your facility layout, lifting height, and environmental conditions.\",\"choose_image\":\"admin\\/20260527\\/bc3eef13d7136b3c010df8c74e9d1d00.webp\",\"choose_image_active\":\"admin\\/20260527\\/bc3eef13d7136b3c010df8c74e9d1d00.webp\"},{\"choose_name\":\"Global Support\",\"choose_desc\":\"24\\/7 technical assistance, spare parts delivery, and onsite commissioning.\",\"choose_image\":\"admin\\/20260527\\/a0b999db3846ed6c0ef248ee1b2a7dd4.webp\",\"choose_image_active\":\"admin\\/20260527\\/a0b999db3846ed6c0ef248ee1b2a7dd4.webp\"},{\"choose_name\":\"Cost-Effective ROI\",\"choose_desc\":\"Energy-efficient drives and low maintenance costs maximize your investment.\",\"choose_image\":\"admin\\/20260527\\/9f36d3ed93369d35d1db1375382411bc.webp\",\"choose_image_active\":\"admin\\/20260527\\/9f36d3ed93369d35d1db1375382411bc.webp\"}],\"faq_title\":\"FAQ\",\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"If you can not find the answer, contact us and let us know how we can help you.\",\"faq_contact_btn_text\":\"Contact Us\",\"faq\":[{\"question\":\"What factors affect crane prices most, and how can I get a reasonable quotation?\",\"answer\":\"Many customers worry about hidden costs and inconsistent pricing when buying cranes. The actual crane price mainly depends on lifting capacity, span, lifting height, working duty, configuration standards and customized functions. Simple standard models have stable and transparent prices, while special working conditions such as explosion-proof, high-temperature, anti-corrosion and intelligent anti-sway systems will lead to different costs. We provide one-on-one tailored quotes based on your actual site conditions and usage needs, with no hidden charges, and every configuration and cost item is clearly listed for your reference.\"},{\"question\":\"Are your cranes suitable for my local industrial and environmental conditions?\",\"answer\":\"This is the key concern for overseas buyers, as different countries have different weather, site and industry requirements. Our overhead cranes, gantry cranes and port cranes can be fully adapted to various complex environments, including high temperature, heavy rain, coastal humidity, dust and strong wind conditions. We can adjust motor brands, electrical systems, anti-rust painting standards, protection grades and wind-proof devices according to your local climate, site environment and industry standards, ensuring long-term stable operation in your working scenario.\"},{\"question\":\"Do you support customized crane solutions for special working conditions?\",\"answer\":\"Standard cranes cannot meet all project needs, which is why custom solutions are essential for industrial engineering projects. We fully support personalized customization including non-standard span, special lifting height, heavy-duty working level, explosion-proof, insulation, anti-corrosion, intelligent anti-sway, remote control and automatic positioning functions. Whether it is factory indoor handling, outdoor yard operation, port container handling or metallurgy and chemical special scenarios, we can design and produce exclusive crane equipment according to your drawings and technical requirements.\"},{\"question\":\"What certifications do your cranes have for overseas export?\",\"answer\":\"Most overseas projects require official certification for customs clearance and project acceptance, which is a major pain point for many purchasers. All our cranes are manufactured in strict accordance with international standards and have complete export qualifications, including CE, ISO and other mainstream certifications. We can provide complete certification documents, inspection reports and factory qualification materials to ensure smooth customs clearance, local inspection and long-term project use in your country.\"},{\"question\":\"What after-sales support can you provide for overseas clients?\",\"answer\":\"Overseas customers are most worried about no technical support and difficult maintenance after purchasing equipment. We provide full-cycle after-sales service including installation guidance, operation training, remote technical support and lifetime after-sales consultation. We supply original spare parts at factory prices for long-term maintenance. If you encounter operation failure, equipment debugging or daily maintenance problems, our professional technical team can respond quickly to help you solve problems and ensure the cranes run stably for a long time.\"}]}'),
('8', '0', 'about_site', '{\"top_title\":\"HENAN WEIHUA GROUP\",\"top_text\":\"Henan Weihua Crane Co.,Ltd. located in crane hometown of China (cover more than 2\\/3 crane market in China), could supply you all kinds of industry cranes and other lifting equipment,more than 110 types, and capacity could be from 0.25tons to 900tons, pass GB\\/T 19001-2000 idt ISO 9001:2000, GB\\/T 24001-2004 idt ISO 14001:2004, GB\\/T 28001-2001,OHSAS 18001:1999, CE, GOST, SGS, TUV, BV and so on. \\r\\n\\r\\nOur Group have more than 4,500 employees, include one experienced and professional team for oversea market. We cover an area of 1,620,000 square meters, hold capital of RMB1.18 Billion, have more than 430 branches around the world and serving over 6,000 mid-to-high-end customers. \",\"middle_text\":\"Meanwhile, our factory have passed CE, EAC, SGS, and OHSAS &amp; ISO9001:2000, ISO14001:1996 and ISO9001:2001, have the perfect quality-control system.\\r\\n\\r\\nWe have one most experienced and professional team for oversea market, who are the earliest one to open the industry crane oversea market in China, now our team have been one famous leading flag for industry crane exporting in China, In addition, we could supply you the turn-key project includes installation, commissioning, training and so on.\",\"bottom_image\":\"admin\\/20250103\\/6ba2f136e516413a5eb456007aba88c6.png\",\"essence\":\"PRACTICAL; HONEST, RESPONSIBLE: THANKFUL: RIGHTFUL; PASSIONAL, CORE CREATE MOREAND MORE PEOPLE TO BE SUCCESSFUL\",\"working_methods\":\"PROFESSION + CONCENTRATION + CIRCUMSPECTION + CONFIDENCE + PATIENCE+PERSEVERANCE + DETERMINATION.\",\"wolves_spirit\":\"COOPERATION+ UNITY + PATIENCE + WILD+ ALL OUT\",\"certificate_images\":[{\"url\":\"portal\\/20250107\\/c44a15d6d978639388e5b8963d73805e.webp\",\"name\":\"葫芦.webp\"},{\"url\":\"portal\\/20250107\\/d68576c4fb1191dc730e9360094253fa.webp\",\"name\":\"门机.webp\"},{\"url\":\"portal\\/20250107\\/45de437d1145a57af8db1a954be02580.webp\",\"name\":\"桥机.webp\"},{\"url\":\"portal\\/20250106\\/0d737e870bc7d14add04c281d1790fb0.webp\",\"name\":\"桥机门机船用港机葫芦绞车.webp\"},{\"url\":\"portal\\/20250106\\/5c3dcabd477f3ccafbe03d90bef9569f.webp\",\"name\":\"桥机门机船用港机葫芦绞车2.webp\"},{\"url\":\"portal\\/20250106\\/7f9321ace309d3815c3f245d2dcab5ae.webp\",\"name\":\"桥机门机船用港机葫芦绞车3.webp\"},{\"url\":\"portal\\/20250106\\/21b4c57e5d26b37ce32089a8c860c939.webp\",\"name\":\"液压伸缩起重机.webp\"},{\"url\":\"portal\\/20250106\\/be5457d157b9ce5826a2bd349646d312.webp\",\"name\":\"液压旋转起重机.webp\"}],\"top_image\":\"admin\\/20250103\\/5bbf57c0bafc0480024947c0f473668e.png\",\"introduction\":\"Founded in 2005 and headquartered in Xinxiang, Henan Province, China, Xinxiang Nucleon (Xinxiang) Crane Co., Ltd. is a leading manufacturer specializing in the research, development, production, and sales of overhead cranes, gantry cranes, electric hoists, jib cranes and port cranes etc.. Nucleon has a registered capital of 80 million US dollars, covering an area of 430000 square meters, and owns more than 1500 employees. The company has equipped over 3000 sets of production and testing equipment, providing support for the research and development of high-quality crane equipment. The leading products have been widely used in pillar industries of the national economy such as metallurgy, energy and power, petrochemicals, railways, and aviation, and exported to various parts of the world.\",\"left_image\":\"admin\\/20260608\\/9e2393cb11713c428bcdaee0d43fcbe7.jpg\",\"do_desc\":\"At Weihua, we pursue technology-driven development and enhance our products and systems to the next level of automation by applications of artificial intelligence and IoT technology. We provide customers with bridge cranes, gantry cranes, electric hoists, intelligent multifunctional cranes, Automated Guided Vehicles (AGVs), bulk material handling equipment, port equipment &amp; comprehensive solutions, and the solutions for turn-key material hoisting and handling engineering.\",\"service_desc\":\"Our customers are mainly in the fields of metallurgy, steel, power, manufacturing, mining, railway, &lt;br&gt;\\r\\n\\r\\naerospace, petroleum, natural gas, chemical industries, ports, etc.\",\"market_description\":\"Nucleon is committed to the global market and strictly adheres to international crane standards. The company has introduced advanced production equipment to ensure that product craftsmanship and quality meet high international standards. Our products have been exported to over 100 countries and regions worldwide, reaching markets such as the Middle East, Southeast Asia, Africa, and the Americas. We provide global customers with safe, reliable, efficient, and intelligent integrated lifting and material handling solutions. At the same time, Nucleon actively responds to China&#039;s &quot;Belt and Road&quot; initiative and steadily advances its internationalization strategy.\",\"cert_description\":\"Quality is the cornerstone of Nucleon&#039;s operations. The company adheres to international standards during production, utilizing high standard raw materials and advanced manufacturing processes to ensure the highest product quality. Additionally, Nucleon Crane has established a comprehensive quality management system, overseeing every stage from design to after-sales service.\\r\\n\\r\\nSafety is a top priority at Nucleon. We incorporate multiple safety features into our product designs and conduct regular maintenance and inspections to ensure the safe operation of our crane equipment. Our goal is to provide customers with secure and dependable hoisting equipment, significantly reducing the risk of accidents.\",\"market\":[{\"market_name\":\"Southeast Asia Market\",\"market_num\":\"16\"},{\"market_name\":\"Europe, America And Australia Market\",\"market_num\":\"88\"},{\"market_name\":\"CIS Market\",\"market_num\":\"17\"},{\"market_name\":\"Middle East And Africa Market\",\"market_num\":\"78\"}],\"advantage\":[{\"advantage_name\":\"Nucleon has a registered capital of 80 million US dollars\",\"advantage_num\":\"80\",\"advantage_unit\":\"Million\"},{\"advantage_name\":\"Nucleon covering an area of 430000 square meters\",\"advantage_num\":\"430000\",\"advantage_unit\":\"m²\"},{\"advantage_name\":\"Nucleon owns more than 1500 employees.\",\"advantage_num\":\"1500\",\"advantage_unit\":\"Employees\"},{\"advantage_name\":\"Nucleon has equipped over 3000 sets of production and testing equipment\",\"advantage_num\":\"3000\",\"advantage_unit\":\"Sets\"}],\"cert\":[{\"url\":\"admin\\/20260515\\/f4f3fa8afad001212da6b855ff63ae2a.webp\",\"name\":\"CE Certificate 2.webp\",\"desc\":\"1\"},{\"url\":\"admin\\/20260515\\/64ac0804e157e8438ffbbb0316515698.webp\",\"name\":\"CE Certificate 3.webp\",\"desc\":\"2\"},{\"url\":\"admin\\/20260515\\/b78638a8a2099069c9145a160ee89177.webp\",\"name\":\"CE Certificate.webp\",\"desc\":\"3\"},{\"url\":\"admin\\/20260515\\/c92b85eb43f57a6ad49797967116a562.webp\",\"name\":\"iso500001.webp\",\"desc\":\"4\"},{\"url\":\"admin\\/20260515\\/7e85bc2d54340a2a78c34768062de1fe.webp\",\"name\":\"ISO 14001 2015.webp\",\"desc\":\"5\"},{\"url\":\"admin\\/20260515\\/d072fe8c016ce3ae993ef0910028d557.webp\",\"name\":\"ISO 45001.webp\",\"desc\":\"6\"},{\"url\":\"admin\\/20260515\\/e1897a1ce42bbe46df326ba26ce9f049.webp\",\"name\":\"ISO9001 2015.webp\",\"desc\":\"78\"},{\"url\":\"admin\\/20260515\\/f92282ae5311f64656db31d4510315ea.webp\",\"name\":\"ISO9001.webp\",\"desc\":\"8\"},{\"url\":\"admin\\/20260515\\/9b5dc948e708f36466c30da7c90f040c.webp\",\"name\":\"ISO45001.webp\",\"desc\":\"9\"},{\"url\":\"admin\\/20260515\\/4b004b86ab8c79bb4d15aa81194748ab.webp\",\"name\":\"ISO 9001.webp\",\"desc\":\"10\"},{\"url\":\"admin\\/20260515\\/96b47601b52f8c6f3a81b11c0b9e12c0.webp\",\"name\":\"ISO 14001.webp\",\"desc\":\"110\"},{\"url\":\"admin\\/20260515\\/86a221d9c032352d41833b4564835651.webp\",\"name\":\"OHSAS 18001.webp\",\"desc\":\"120\"}],\"corporate_images\":[{\"url\":\"admin\\/20260401\\/1ecacaeff2bc05b0816a37a677334d2a.jpg\",\"name\":\"Portal Crane\"}],\"create\":[{\"create_name\":\"Innovation\",\"create_desc\":\"Weihua has 33 national and provincial-level research and development platforms, relying on 7 major research and development centers at home and abroad and a research team of more than 1000 people. It has undertaken 7 major national projects and has more than 1200 authorized patents. Its independently developed electrical anti sway control technology is internationally leading, with a 400 meter ultra-high winch setting the world record for the largest lifting height. The AICrane intelligent control system creates a true lifting robot, and the new Chinese crane defines a new concept and promotes the lifting of new cranes China&#039;s lifting technology is constantly iterating and updating.\",\"create_image\":\"admin\\/20260513\\/33c64c55712ae745ab7b1f830a1d2d38.webp\"},{\"create_name\":\"Ingenuity\",\"create_desc\":\"The production process of Weihua products is equipped with advanced and complete crane manufacturing technology, supporting equipment, and tooling systems. From steel pre-treatment, cutting, welding, to assembly, heat treatment, and painting, the entire product production process has strict process requirements and quality standards, ensuring that all aspects of product production meet process requirements and high quality standards.\",\"create_image\":\"admin\\/20260513\\/5c972b8bbc97a02adccf547c4072b782.webp\"},{\"create_name\":\"Creation\",\"create_desc\":\"Weihua has always taken internationalization, greening, intelligence, and digitization as its development strategy, with the goal of building a world-class high-end intelligent factory. Relying on the three major production bases of Changyuan, Zhengzhou, and Jiangsu, Weihua has built intelligent production workshops, equipped with robot welding and spraying intelligent production lines, specializing in the research and development and manufacturing of various lifting equipment, marine equipment, high-end intelligent equipment, etc. It produces more than 100000 sets of intelligent lifting logistics equipment and supporting products annually.\",\"create_image\":\"admin\\/20260513\\/3880cf30815b15b090737e5c55cefb8f.webp\"},{\"create_name\":\"Quality\",\"create_desc\":\"Quality is the lifeline of Weihua, and Weihua regards comprehensive quality management as the central link of enterprise management. The testing reports issued by Weihua National Accreditation Laboratories can be exchanged and recognized with more than 70 countries around the world. We have over 300 sets of testing equipment, including a 1000 ton test bench and a 100 ton electric hoist test bench. From raw materials and supporting components entering the factory to finished products leaving the factory, we establish strict process and testing standards at 180 main control nodes to ensure that the mechanical components are fully controlled.\",\"create_image\":\"admin\\/20260513\\/8fa75543c6b46df22480996749987fc6.webp\"}],\"service_bg\":\"admin\\/20260513\\/39f18ef28993741eb87c5938f5f434cd.webp\",\"market_image\":\"admin\\/20260608\\/65de4a9b8c65e68f2fc11b10765c850e.webp\",\"culture_bg\":\"admin\\/20260608\\/01fc941c4271a1104f97e4ef6c164233.jpg\",\"culture_card_bg\":\"admin\\/20260608\\/72181e3ce6ec5b23b34fc87cb2097cc7.png\",\"service_description\":\"Devoted to the development and research of cranes and material handling technologies\",\"engineering\":[{\"title\":\"Technical consultation and negotiation\",\"image_normal\":\"admin\\/20260608\\/94f198a5ee8e1cf2164eca79f4978cd8.webp\",\"image_active\":\"admin\\/20260608\\/f108f370f483b913b849114b2baa85aa.webp\"},{\"title\":\"Free design\",\"image_normal\":\"admin\\/20260608\\/da0377012184b521a4ab2f15f72931ed.webp\",\"image_active\":\"admin\\/20260608\\/1d5f0f2f6cda070db5c2fd214d6ebac1.webp\"},{\"title\":\"Installation and commissioning\",\"image_normal\":\"admin\\/20260608\\/0877dca02ac26cf2c8ea36b7d20a47a2.webp\",\"image_active\":\"admin\\/20260608\\/4bc8aa0fd3a4887e66355036f5208b81.webp\"},{\"title\":\"Training\",\"image_normal\":\"admin\\/20260608\\/a84d22dcaa9d7df41957171e238cb423.webp\",\"image_active\":\"admin\\/20260608\\/0506853e9deacb4900580b011cbcdd82.webp\"},{\"title\":\"Return visit\",\"image_normal\":\"admin\\/20260608\\/1b04ffab3594abbd46185cf81ffa843b.webp\",\"image_active\":\"admin\\/20260608\\/e371536f47a4fdcca1159f0c08d61800.webp\"},{\"title\":\"7*24 hours service\",\"image_normal\":\"admin\\/20260608\\/ce75733c53ed5a76a40aaf84fcea6ba2.webp\",\"image_active\":\"admin\\/20260608\\/aa7e28f452a53fc0338e8756860d595a.webp\"}],\"service_items\":[{\"title\":\"PRE-SALE SERVICE\",\"text\":\"Each department of the technical system has established a unified technical design and management platform - PLM system, which achieves resource sharing, unified data management, collaborative design, and remote collaborative design modes. Advanced design analysis software such as SolidWorks and SolidEdge are widely used, and the mainstream design methods based on CAD design, CAE analysis, digital modeling, and motion simulation are the main means of research and development.\\r\\nWe have adopted advanced parametric bridge crane CAD design and analysis software developed in cooperation with Huazhong University of Science and Technology in China. From quotation and scheme design to the generation of construction drawings that can be directly used in production, it can automatically generate. Various modern design and processing methods such as PDM, CAD, CAE, CAM, and CAPP are used to achieve optimized design and research and development of products.\",\"image\":\"admin\\/20260608\\/95d96e8e0825da54d1c94075dc0d0f5b.webp\"},{\"title\":\"IN-SALE SERVICE\",\"text\":\"Nucleon is committed to providing customers with systematic solutions, as well as streaming services and support. Faced with the sincere trust of tens of thousands of customers, Nucleon adheres to the service philosophy of &quot;enthusiasm, speed, professionalism, and perfection&quot;, systematizing, standardizing, and branding its service work.\",\"image\":\"admin\\/20260608\\/55fc1ccc952d9b78e6769e85ca9c9e3d.webp\"},{\"title\":\"AFTER-SALE SERVICE\",\"text\":\"1.Any quality problems arising from various products produced and sold by our company shall be covered by the &quot;three guarantees&quot; service provided by our company in accordance with regulations, and the sales and service three guarantees team shall undertake this work.\\r\\n2. After receiving information from users about product quality (such as phone calls, letters, or verbal notifications), immediately dispatch relevant personnel to the site to handle and solve the problem.\\r\\n3. After sales service personnel should handle quality issues seriously, thoughtfully, and thoroughly to ensure timely use by users without any worries.\\r\\n4. While promptly resolving quality issues with sold products, after-sales service personnel have the obligation to provide free technical consultation, training, and answer other product related questions to users.\\r\\n5.Firmly establish the idea that the user is God and everything is for the sake of the user, handle quality issues promptly, seriously, and from start to finish, pay attention to reputation, maintain the company&#039;s image everywhere, and ensure the company&#039;s peace of mind and customer satisfaction.\",\"image\":\"admin\\/20260608\\/6b98679b1cb8653372c2004d34a462f1.webp\"}]}'),
('9', '1', 'quote_site', '{\"image\":\"admin\\/20260507\\/37b85d2ed91b2b3502b7ab3a646042c9.webp\",\"commitments\":[{\"title\":\"60S\",\"desc\":\"Inquiry arrives at the manager within 60 seconds\",\"image\":\"\"},{\"title\":\"30M\",\"desc\":\"Technical Q&amp;A within 30 minutes\",\"image\":\"\"},{\"title\":\"24H\",\"desc\":\"Provide design plan within 24 hours\",\"image\":\"\"},{\"title\":\"72H\",\"desc\":\"Engineer dispatch within 72 hours\",\"image\":\"\"},{\"title\":\"365D\",\"desc\":\"Accept service demand 365 days\",\"image\":\"\"}]}'),
('10', '0', 'service_site', '{\"first_title\":\"Installation guide\",\"first_description\":\"We can arrange professional installation engineers to guide the installation work on site, so that the equipment can be put into use as soon as possible after arriving at the site.\\r\\n\",\"first_image\":\"admin\\/20260324\\/518d330b37082b64948a5b9cec47411d.webp\",\"second_title\":\"Crane training and learning\",\"second_description\":\"During the equipment installation process, the installation engineer will organize personnel to carry out crane professional knowledge training and operation training.In addition, we can also provide in-plant training. If you have needs, you can arrange personnel to study on site in our company.\",\"second_image\":\"admin\\/20260324\\/6c80122869007cdc7e6cb46f3535401a.webp\",\"third_title\":\"Installation Service\",\"third_description\":\"We can arrange engineers to your factory to do supervision of the installation, commissioning. The installation service is available for every item we sell. Experienced and qualified technicians install cranes and accessories at our client’s convenience. A range of accessories such as remote-control systems and variable speed control device and so on is also available.\",\"third_image\":\"admin\\/20260324\\/54e0b24930c81fa95c05feadbb0d95dd.webp\",\"fourth_title\":\"After-sales maintenance\",\"fourth_description\":\"We guarantee product quality. If you have any questions or problems during use, you can contact us at any time. Our company has also set up permanent offices in four countries, and is also authorized brand agent in many countries. Your crane usage problem can be solved in a short time.\",\"fourth_image\":\"admin\\/20260324\\/f2b88e58ca88bdc5da1bc7ba1cdb9a16.webp\",\"internationalization\":\"Weihua actively implements the national &quot;Belt and Road&quot; initiative, firmly promotes the internationalization strategy, and has established more than 100 overseas marketing service agencies in Southeast Asia, the Middle East, Africa, South America and other regions.\",\"internationalization_image\":\"admin\\/20260401\\/1dbc2b835c2486b28b93bb14ecd33f62.webp\",\"areas\":[{\"area\":\"Southeast Asia Market\",\"country\":\"18\",\"color\":\"#EC212F\"},{\"area\":\"Middle East and Africa Market\",\"country\":\"75\",\"color\":\"#1E1B1E\"},{\"area\":\"Europe, America and Australia Market\",\"country\":\"88\",\"color\":\"#23BAEB\"}],\"left_title\":\"Weihua overseas business center has 50 employees\",\"left_desc\":\"who are proficient in Spanish, French, English and other languages, and can meet the needs of project communication. Weihua overseas market is divided into four sales regions\",\"right_title\":\"Exported to more than 130 countries and regions\",\"right_desc\":\"At present, Weihua products have been exported to more than 130 countries and regions, and have participated in the construction of many large overseas projects.\",\"companies\":[{\"url\":\"admin\\/20260514\\/c12620e6306b406fe8f83c0929f73bb1.webp\",\"name\":\"图片-1.webp\"},{\"url\":\"admin\\/20260514\\/787467308a4c38c5b24e888e65e60dcf.webp\",\"name\":\"图片-2.webp\"},{\"url\":\"admin\\/20260514\\/6a832e95c892cd9d1bcedce330495218.webp\",\"name\":\"图片-3.webp\"},{\"url\":\"admin\\/20260514\\/d3ad0ed5781b8f04cf19119fa4f21257.webp\",\"name\":\"图片-4.webp\"},{\"url\":\"admin\\/20260514\\/7ed56d13f538a22fab4ead0283a627db.webp\",\"name\":\"图片-5.webp\"},{\"url\":\"admin\\/20260514\\/e374122583623330ff2a91df84bf2464.webp\",\"name\":\"图片-6.webp\"},{\"url\":\"admin\\/20260514\\/358152b9c06908f0264c3ba56991a2a5.webp\",\"name\":\"图片-7.webp\"},{\"url\":\"admin\\/20260514\\/5982415ba6c82bd43e9f47fbe397a2d0.webp\",\"name\":\"图片-8.webp\"},{\"url\":\"admin\\/20260514\\/1f443519828f2a13db38ea5446973c37.webp\",\"name\":\"图片-9.webp\"},{\"url\":\"admin\\/20260514\\/1a1331f870fa18893f7799282a7e48ef.webp\",\"name\":\"图片-10.webp\"}],\"cards\":{\"1780971339135932\":{\"title\":\"Customization Design\",\"icon\":\"\",\"desc\":\"Nucleon Crane has professional engineer department, offering tailored lifting solution based on your actual requirements.\"},\"1780971353379253\":{\"title\":\"Installation Guidance\",\"icon\":\"\",\"desc\":\"For heavy lifting overhead cranes or gantry cranes, we could offer on-site installation service or guidance to make sure the equipment work smoothly.\"},\"1780971372563942\":{\"title\":\"Free Spare Parts\",\"icon\":\"\",\"desc\":\"If your crane equipment needs spare parts to replace, we could provide you with free spare parts for the first year.\"},\"1780971391680538\":{\"title\":\"Warranty Service\",\"icon\":\"\",\"desc\":\"Quality is always the most important concern of the crane equipment. Our overhead cranes and gantry cranes have 5-year warranty service to guarantee safe operation of each product.\"},\"1780971410113955\":{\"title\":\"Online Communication\",\"icon\":\"\",\"desc\":\"We provide 24 Hours online communication service for each client. For more information or product details, feel free to contact us anytime.\"}},\"packaging_title\":\"Packaging &amp; Shipping\",\"packaging_items\":{\"1780971022486874\":{\"img\":\"admin\\/20260609\\/e6dcfa3f66b547263e1b16b0bfec9145.png\",\"name\":\"Big Car Packaging\"},\"1780971220551648\":{\"img\":\"admin\\/20260609\\/6203e764644f7827205770a39ac95c96.png\",\"name\":\"High Speed Logistics\"},\"1780971259238424\":{\"img\":\"admin\\/20260609\\/b3c960f693109917ceb39073d0b45905.png\",\"name\":\"Container Loading\"},\"1780971278726679\":{\"img\":\"admin\\/20260609\\/1b7f575d5d877169cec83904eeb4b3e7.png\",\"name\":\"Sea Transportation\"}},\"cooperation_title\":\"Cooperation Process\",\"cooperation_items\":{\"1780971830063339\":{\"img\":\"admin\\/20260609\\/8f64cc72b1ab5402ff1190a8da63de22.png\",\"icon\":\"iconfont a-Frame189\",\"name\":\"Contract Signing\"},\"1780971985215137\":{\"img\":\"admin\\/20260609\\/e56e0325ac3c58357e24d17607c2489b.png\",\"icon\":\"iconfont kache\",\"name\":\"Delivery\"},\"1780972011454458\":{\"img\":\"admin\\/20260609\\/28b9945dca31eb0daaa8ddcc4bb83ad0.png\",\"icon\":\"iconfont a-Frame189\",\"name\":\"Online Communication\"},\"1780972035697589\":{\"img\":\"admin\\/20260609\\/c8fb6c559c177eb889372b1fadeb846b.png\",\"icon\":\"iconfont kache\",\"name\":\"Product Manufacturing\"}},\"support_title\":\"Technical Support\",\"support_items\":{\"1780972060142753\":{\"img\":\"admin\\/20260609\\/ea7bab814a24a050411436cb5d00a68c.png\",\"name\":\"24 Hours Online Serice\"},\"1780972079282467\":{\"img\":\"admin\\/20260609\\/b0ce480825721b652956b7afcafe038d.png\",\"name\":\"Customized Design\"},\"1780972086198259\":{\"img\":\"admin\\/20260609\\/2b912d78a9a46ed305091188783a8229.png\",\"name\":\"Installation Guidance\"},\"1780972091423165\":{\"img\":\"admin\\/20260609\\/7cace83c18adda69f6f03c7aec64bbf0.png\",\"name\":\"Operation Training\"}},\"aftersales_title\":\"After-sales Service\",\"aftersales_img_left\":\"admin\\/20260609\\/421118a71f80ec1e7eb2d265fb562bce.png\",\"aftersales_img_mt\":\"admin\\/20260609\\/dbfd01034169f7778bdc828c5745a0d9.png\",\"aftersales_text_mt\":\"Free Spare Parts\",\"aftersales_img_mb\":\"admin\\/20260609\\/c103b03d1d3f7ed6e8d32d90ac329230.png\",\"aftersales_text_mb\":\"Warranty Serivce\",\"aftersales_img_right\":\"admin\\/20260609\\/58783eddbd06a6679a57710517dbff76.png\"}'),
('11', '1', 'excellent_service_site', '{\"title1\":\"Installation guide\",\"content1\":\"We can arrange professional installation engineers to guide the installation work on site, so that the equipment can be put into use as soon as possible after arriving at the site\",\"image1\":\"admin\\/20260401\\/89da93d1750058e81300fff72ef904d2.jpg\",\"title2\":\"Crane training and learning\",\"content2\":\"During the equipment installation process, the installation engineer will organize personnel to carry out crane professional knowledge training and operation training. In addition, we can also provide in-plant training. If you have needs, you can arrange personnel to study on site in our company.\",\"image2\":\"admin\\/20260401\\/b0d3d5055e5e246d1bcf3691ebba1989.jpg\",\"title3\":\"After-sales maintenance\",\"content3\":\"We guarantee product quality. If you have any questions or problems during use, you can contact us at any time. Our company has also set up permanent offices in four countries, and is also authorized brand agent in many countries. Your crane usage problem can be solved in a short time.\",\"image3\":\"admin\\/20260401\\/9d385b3c30f5662a4e303852be1eb69b.jpg\",\"title4\":\"Installation Service\",\"content4\":\"We can arrange engineers to your factory to do supervision of the installation, commissioning. The installation service is available for every item we sell. Experienced and qualified technicians install cranes and accessories at our client’s convenience. A range of accessories such as remote-control systems and variable speed control device and so on is also available.\\r\\n\\r\\n\",\"image4\":\"admin\\/20260401\\/b2b0452c4497ad24de4537a3687e58af.jpg\"}'),
('12', '1', 'product_category_hero_settings', '{\"28\":{\"title\":\"Overhead Crane Manufacturer | Custom Lifting Solutions\",\"description\":\"We supply single girder and double girder overhead cranes with customizable load capacity from 1 ton to 100 tons. We offer personalized design, professional on-site installation and complete after-sales support. Factory direct sales with full global certifications, ideal for factories, warehouses and workshops.\",\"selector_title\":\"How to Choose the Right Overhead Crane?\",\"selector_description\":\"If you haven’t decided yet, tell us your lifting load, span, workshop space and working conditions. You may also send factory layout plans. We will recommend the most suitable and budget-friendly overhead crane solution for you.\",\"selector_button_text\":\"Get Professional Advice\",\"selector_items\":[{\"scene\":\"General workshops, warehouses and light-duty production lines\",\"type\":\"LD Single Girder Overhead Crane\"},{\"scene\":\"Heavy industry workshops, machinery manufacturing and large processing plants\",\"type\":\"Double Girder Overhead Crane\"},{\"scene\":\"Petrochemical plants, gas stations and flammable explosive working zones\",\"type\":\"Explosion-proof Bridge Crane QB Type\"},{\"scene\":\"Low ceiling factories, compact workshops and restricted indoor spaces\",\"type\":\"Low Headroom Overhead Crane\"},{\"scene\":\"Workstation processing areas, assembly lines and local material handling zones\",\"type\":\"Floor-Mounted Jib Crane\"}],\"icon\":\"portal\\/20260526\\/dc3cacbfca4307a60e05bfb66f1d7e58.png\"},\"19\":{\"title\":\"Gantry Crane Supplier | Custom Outdoor Lifting Cranes\",\"description\":\"Durable single and double girder gantry cranes available in various specifications. Fully customized to fit your site conditions, equipped with reliable safety performance. We provide one-stop installation service and long-term after-sales maintenance, certified quality and competitive factory price.\",\"selector_title\":\"How to Choose the Right Gantry Crane?\",\"selector_description\":\"If you are still hesitating, simply inform us your lifting capacity, working span, yard space and actual operating needs. You can also share site layout drawings, and we will match you with practical and cost-effective gantry crane solutions.\",\"selector_button_text\":\"Submit Your Requirements\",\"selector_items\":[{\"scene\":\"Outdoor cargo yards, freight stations and heavy goods stacking sites\",\"type\":\"Double Girder Gantry Crane U Type\"},{\"scene\":\"Industrial sites, overseas engineering projects and high-standard logistics yards\",\"type\":\"FEM\\/DIN Double Girder Gantry Crane\"},{\"scene\":\"Side workshop passages, edge operation areas and space-saving outdoor working places\",\"type\":\"Semi Gantry Crane BMG Type\"},{\"scene\":\"Small outdoor yards, construction sites and light-duty outdoor handling places\",\"type\":\"MH Gantry Crane with Electric Hoist\"},{\"scene\":\"Open-air stockyards, railway freight yards and outdoor light cargo loading and unloading sites\",\"type\":\"L Type Single Girder Gantry Crane\"}],\"icon\":\"portal\\/20260526\\/3f915c1b01cc05b6bbf63fd0864cd3ec.png\"},\"22\":{\"title\":\"High Temperature Metallurgical Crane | Custom Heavy Duty Crane\",\"description\":\"Professional heavy-duty metallurgical cranes tailored for high temperature working environment. Custom load range and protective configurations available. Complete installation guidance and thoughtful after-sales service are provided, stable and safe for steel mill and smelting industry use.\",\"selector_title\":\"How to Choose the Right Metallurgy Crane?\",\"selector_description\":\"If you are unsure which metallurgy crane fits your production needs, just let us know your required lifting capacity, workshop span, lifting height, and actual working duty. You can also send us your workshop layout and high-temperature working environment details. We will recommend well-matched, safe and durable customized metallurgy crane solutions for your smelting and steelmaking production.\",\"selector_button_text\":\"Get Professional Advice\",\"selector_items\":[{\"scene\":\"High-temperature smelting workshops, steel mills and molten metal pouring &amp; transporting stations\",\"type\":\"Crane for Meltshop | Ladle Cranes\"},{\"scene\":\"Steel stockyards, processing workshops and heavy bulk metal material clamping &amp; transfer areas\",\"type\":\"Clamps Overhead Crane\"},{\"scene\":\"Steelmaking workshops, non-ferrous metal processing and high-temperature metallurgical production lines\",\"type\":\"Overhead Crane for Metallurgy\"},{\"scene\":\"Heavy-duty smelting workshops, molten metal handling and continuous metallurgy production sites\",\"type\":\"Metallurgy Overhead Crane QDY Type\"},{\"scene\":\"Foundry factories, casting production lines and high-temperature molten material operation areas\",\"type\":\"Foundry Casting Bridge Crane YZ Type\"}],\"icon\":\"\"},\"23\":{\"title\":\"Port Crane Manufacturer | Custom Dock Handling Equipment\",\"description\":\"High-efficiency port cranes for container and bulk cargo handling. All specifications can be customized according to terminal demands. We provide overall project matching, on-site commissioning and global after-sales service, certified products to meet international shipping operation standards.\",\"selector_title\":\"How to Select Suitable Port Cranes?\",\"selector_description\":\"If you feel confused about picking ideal port handling cranes, just tell us your required load capacity, working radius, berth size and daily cargo throughput. You may also send over your port layout and operation plans. We will tailor reliable, budget-friendly port crane solutions perfectly fitting your actual terminal working conditions.\",\"selector_button_text\":\"Check Best Crane Solution\",\"selector_items\":[{\"scene\":\"Flexible container yard operation, terminal container stacking, mobile cargo arrangement, no fixed rail restriction\",\"type\":\"Rubber Tyred Container Gantry Cranes\"},{\"scene\":\"Large container terminals, high-density container storage areas, high-efficiency automated port logistics zones\",\"type\":\"RMG Rail Mounted Container Gantry Cranes\"},{\"scene\":\"Coastal large wharves, international freight ports, large vessel container loading and unloading operations\",\"type\":\"Ship-to-Shore Container Cranes\"},{\"scene\":\"River wharves, inland ports, bulk cargo terminals and general cargo berth handling work\",\"type\":\"MQ Portal Crane\"},{\"scene\":\"Yacht marinas, shipyards, leisure boat docks, vessel launching and daily docking transfer scenarios\",\"type\":\"Boat and Yacht Handling Crane\"}],\"icon\":\"portal\\/20260526\\/0c759480df34db15f30962a90a48fdff.png\"},\"25\":{\"title\":\"Light Crane Supplier | Custom Light Lifting Crane Solutions\",\"description\":\"We offer versatile light cranes with flexible specifications and customizable designs. Suitable for small workshops, warehouses and light duty handling work. Full installation service and reliable after-sales support available. Certified quality with factory direct price\",\"selector_title\":\"How to Choose the Right Light Crane?\",\"selector_description\":\"If you are unsure which light lifting equipment fits your needs, just let us know your required lifting weight, installation space, working height and daily usage frequency. You can also send us your workshop layout and working area plans. We will recommend well-matched, space-saving and budget-friendly light crane solutions for you.\",\"selector_button_text\":\"Request Quick Quotation\",\"selector_items\":[{\"scene\":\"Independent workshop zones, processing stations and flexible local material handling areas\",\"type\":\"Free-Standing Jib Crane\"},{\"scene\":\"Long-span production lines, workshop side passages and linear workpiece transfer sites\",\"type\":\"Wall Rail Jib Crane\"},{\"scene\":\"Chemical plants, oil depots, gas workshops and flammable explosive working environments\",\"type\":\"Explosion-Proof Jib Crane\"},{\"scene\":\"Narrow workshop corners, assembly stations and space-limited indoor operation spots\",\"type\":\"Wall Fixed Jib Crane\"},{\"scene\":\"Factory interior assembly lines, low-rise workshops and compact indoor light cargo conveying places\",\"type\":\"Electric Suspension Crane\"}],\"icon\":\"portal\\/20260526\\/392755e5b1bf24350bf3140108296c30.png\"},\"30\":{\"title\":\"Electric Hoist | Custom Industrial Hoist Supplier\",\"description\":\"Professional electric hoist manufacturer offering custom chain hoist and wire rope hoist. 1–50 ton customizable lifting capacity, globally certified with factory direct pricing.\",\"selector_title\":\"How to Choose the Right Electric Hoist?\",\"selector_description\":\"If you are unsure which electric hoist fits your lifting needs, just let us know your required lifting capacity, lifting height, working speed and daily operating frequency. You can also send us your workshop space conditions and application scenarios. We will recommend well-matched, cost-effective and safe customized electric hoist solutions for your indoor and outdoor material handling work.\",\"selector_button_text\":\"Get Professional Advice\",\"selector_items\":[{\"scene\":\"Flammable and explosive workshops, chemical plants, oil and gas industrial lifting sites\",\"type\":\"HB Explosion-Proof Electric Hoist\"},{\"scene\":\"Precision assembly workshops, factory production lines and lightweight frequent handling scenarios\",\"type\":\"European Electric Hoist\"},{\"scene\":\"Large-span factories, heavy-duty processing workshops and high-precision material moving areas\",\"type\":\"European Hoist Trolley Double Girder\"},{\"scene\":\"General industrial workshops, warehouses and frequent light &amp; medium load lifting operations\",\"type\":\"CD1 MD1 Wire Rope Electric Hoist\"},{\"scene\":\"Construction sites, factory cargo traction and long-distance heavy material pulling scenarios\",\"type\":\"Electric Winch\"}],\"icon\":\"portal\\/20260526\\/84e137e96f2ab47c37fe0200f16f6c94.png\"},\"27\":{\"title\":\"\",\"description\":\"\",\"selector_title\":\"\",\"selector_description\":\"\",\"selector_button_text\":\"\",\"selector_items\":[],\"icon\":\"portal\\/20260526\\/4beb89512983a9fe8187eadf6479e107.png\"}}'),
('13', '1', 'product_category_faq_settings', '{\"28\":{\"faq_title\":\"\",\"faq\":[{\"question\":\"What factors should I consider when choosing a suitable overhead crane?\",\"answer\":\"When buying a overhead crane, many customers only focus on price and end up with equipment that does not match their workshop conditions. The most important factors are lifting weight, workshop span, ceiling height, working frequency and working environment. We configure the most suitable crane solution according to your actual site data, avoiding over configuration wasting budget or insufficient performance affecting production.\"},{\"question\":\"Are your overhead cranes suitable for high-frequency heavy industrial use?\",\"answer\":\"Many ordinary cranes on the market are prone to deformation, motor heating and frequent failures after long-time heavy use. Our single and double girder overhead cranes adopt reinforced steel structure and industrial-grade core components, designed for long-hour, high-frequency factory operation. Stable performance, low failure rate, and effectively reduce your production shutdown losses.\"},{\"question\":\"Can you modify and customize the crane for special workshop conditions?\",\"answer\":\"Many customers have troubles such as low factory ceiling, limited installation space, special rail positions or dust\\/high temperature environment. We support full non-standard customization, including low-headroom design, anti-corrosion, explosion-proof, dust-proof and customized span and height. No need to renovate your workshop, the crane can be perfectly installed and used.\"},{\"question\":\"How about your overseas after-sales service and technical support?\",\"answer\":\"Overseas users are most worried about no technical support and difficult maintenance after purchasing equipment. We provide lifelong online technical guidance, remote debugging and fault diagnosis. Complete English installation manuals, video tutorials and sufficient spare parts support ensure you can solve daily maintenance problems by yourself quickly.\"},{\"question\":\"Do your overhead cranes meet international safety and quality standards?\",\"answer\":\"Unqualified cranes will cause customs detention and potential safety hazards. All our overhead cranes comply with CE, ISO, FEM and other international standards, with complete test reports and certification documents. Strict factory quality inspection ensures stable safety performance and fully meets local industrial safety requirements.\"}],\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"If you can not find the answer, contact us and let us know how we can help you.\",\"faq_contact_btn_text\":\"Contact Us\",\"faq_contact_btn_link\":\"\",\"faq_bg_img\":\"admin\\/20260526\\/95656cd720f7755ece8d8b0eba30b6dc.webp\"},\"30\":{\"faq_title\":\"\",\"faq\":[{\"question\":\"What lifting capacities do your electric hoists cover?\",\"answer\":\"Our electric hoists range from 0.5 ton to 50 ton. Standard and heavy-duty types are both available, fitting daily workshop handling, heavy cargo hoisting and industrial assembly work.\"},{\"question\":\"What working environments can these hoists adapt to?\",\"answer\":\"They support indoor factory, warehouse, construction site and outdoor open areas. Custom anti-corrosion, dustproof and waterproof versions can be made for humid, coastal and harsh working conditions.\"},{\"question\":\"How about running stability and safety performance?\",\"answer\":\"Built with reliable braking and overload protection systems. It runs smoothly with little vibration and noise. All products comply with international safety norms to avoid accidental slipping and ensure operational security.\"},{\"question\":\"Is daily maintenance hard and what is service life?\",\"answer\":\"Structure is compact with few vulnerable parts. Only regular lubrication and simple routine check are needed. Normal use can reach 10-18 years long service life.\"},{\"question\":\"Can you make customized electric hoist solutions?\",\"answer\":\"Sure. We adjust lifting height, running speed and voltage as your demands. Professional technical team offers tailored design to match your overhead crane, jib crane and actual working demands.\"}],\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"If you can not find the answer, contact us and let us know how we can help you.\",\"faq_contact_btn_text\":\"Contact Us\",\"faq_contact_btn_link\":\"\"},\"19\":{\"faq_title\":\"\",\"faq\":[{\"question\":\"What site conditions are suitable for a gantry crane?\",\"answer\":\"Gantry cranes are perfect for outdoor yards, ports, construction sites and workshops without overhead roof rails. It runs on ground rails, requires no factory ceiling support, and fits most open-air material handling scenarios.\"},{\"question\":\"What is the difference between a gantry crane and an overhead crane?\",\"answer\":\"The biggest difference is the installation way. Gantry cranes stand on the ground with steel legs, ideal for outdoor use. Overhead cranes rely on building frames and are mainly for indoor workshops. Most outdoor projects choose gantry cranes for better flexibility.\"},{\"question\":\"Can you customize the span, height and tonnage of gantry cranes?\",\"answer\":\"Yes. We fully customize span, lifting height, capacity, power voltage and control methods. No matter small yard or large port cargo handling, we can adjust the parameters to match your actual site exactly.\"},{\"question\":\"How long is the service life and what about maintenance?\",\"answer\":\"Our heavy-duty gantry cranes feature solid steel structure and wear-resistant parts. With regular simple maintenance, the service life can reach 15–20 years. We provide clear maintenance guidance and global after-sales support.\"},{\"question\":\"What is your delivery time and export service?\",\"answer\":\"Standard gantry crane models have short production cycles. Customized products also have stable lead time. We provide full export packaging, shipping documents, installation manuals and remote technical guidance for overseas clients.\"}],\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"If you can not find the answer, contact us and let us know how we can help you.\",\"faq_contact_btn_text\":\"Contact Us\",\"faq_contact_btn_link\":\"\"},\"23\":{\"faq_title\":\"\",\"faq\":[{\"question\":\"What features make port crane fit seaside harsh working environment?\",\"answer\":\"Built with corrosion resistant materials, it stands wind, salt fog and humid weather. Solid structure keeps stable performance during long term outdoor cargo lifting at docks.\"},{\"question\":\"What cargo types can this port crane handle?\",\"answer\":\"It works well for container goods, bulk materials and heavy port cargo. Suitable for loading, unloading and stock moving tasks at all kinds of seaports and harbors.\"},{\"question\":\"Can we adjust crane size and load capacity for our dock space?\",\"answer\":\"Full customization is available. We tailor span, lifting height and tonnage according to actual dock layout, perfectly matching local operation demands.\"},{\"question\":\"How to guarantee safe running during frequent heavy lifting work?\",\"answer\":\"Equipped with overload protection and anti sway system. Strict factory testing ensures reliable operation, greatly lower accident risks in busy port work.\"},{\"question\":\"What support can you offer after placing order?\",\"answer\":\"We provide complete export documents, professional installation guide and long distance technical support. Fast response solves daily operation troubles timely.\"}],\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"If you can not find the answer, contact us and let us know how we can help you.\",\"faq_contact_btn_text\":\"Contact Us\",\"faq_contact_btn_link\":\"\"},\"25\":{\"faq_title\":\"\",\"faq\":[{\"question\":\"What is the real advantage of a jib crane over bridge cranes?\",\"answer\":\"Unlike bridge cranes that need full overhead rails, a jib crane runs on a single mast or wall mount. It saves 70% floor space, serves localized work zones with 180°–360° rotation, and costs 30–50% less. Perfect for assembly stations, machine shops, and tight warehouses where big cranes are overkill.\"},{\"question\":\"Can you customize jib cranes for my workshop’s limited space?\",\"answer\":\"Absolutely. We tailor capacity (0.25–10 ton), boom length, rotation angle (180°\\/270°\\/360°) and mounting type (freestanding\\/wall-mounted). Wall-mounted models save floor space; freestanding ones need only a small foundation. We’ll even send engineers to check your site and draw free layouts.\"},{\"question\":\"How long does delivery and installation take?\",\"answer\":\"Standard models ship in 2–4 weeks. Custom units (special boom, outdoor coating, etc.) take 6–8 weeks. Installation is quick: wall-mounted in 1 day, freestanding in 2 days. We provide full drawings and video guides; if needed, our technicians can supervise installation onsite.\"},{\"question\":\"Is maintenance complicated? How safe is it?\",\"answer\":\"Super easy. With fewer moving parts than overhead cranes, maintenance only needs monthly lubrication and 6–12 month inspections. All units meet CE\\/ISO standards, with overload protection, emergency stop, and anti-sway devices. Used properly, lifespan reaches 10–20 years. Safety is always our top priority.\"},{\"question\":\"Can jib cranes work outdoors or in harsh environments?\",\"answer\":\"Yes. We offer hot-dip galvanized or painted finishes for rust resistance, plus waterproof and dustproof electrical components. They work reliably in -20°C to +40°C. For coastal or high-humidity areas, we add extra anti-corrosion treatment. Many clients use them in yards, ports, and construction sites without issues.\"}],\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"If you can not find the answer, contact us and let us know how we can help you.\",\"faq_contact_btn_text\":\"Contact Us\",\"faq_contact_btn_link\":\"\"},\"22\":{\"faq_title\":\"\",\"faq\":[{\"question\":\"What makes a metallurgical crane different from ordinary overhead cranes?\",\"answer\":\"Metallurgical cranes are specially upgraded for high-temperature, high-frequency and heavy-duty working conditions. Unlike ordinary workshop cranes, they adopt high-temperature resistant wires, heat insulation protection and reinforced structural parts, which can stably handle molten metal and high-temperature materials in steel mills and smelting plants.\"},{\"question\":\"Can your metallurgical crane work continuously in high-temperature smelting workshops?\",\"answer\":\"Absolutely. Our metallurgical cranes are professionally designed for harsh high-temperature environments. Key components are equipped with heat dissipation and anti-scald protection devices, supporting long-time uninterrupted frequent operation in smelting, casting and steel making workshops, with low failure rate.\"},{\"question\":\"Is your metallurgical crane safe for molten steel and ladle handling?\",\"answer\":\"Yes. All our metallurgical lifting cranes are equipped with double brake protection, overload limit and emergency stop system. The whole machine meets industrial metallurgy safety standards, effectively avoiding slipping and falling risks during molten metal and ladle transportation, ensuring on-site operation safety.\"},{\"question\":\"Can you customize metallurgical cranes for special working conditions?\",\"answer\":\"We support full personalized customization. According to your workshop temperature, lifting tonnage, working frequency and site space, we can adjust the crane span, lifting height, protection grade and control mode, to perfectly match your unique metallurgical production needs.\"},{\"question\":\"What is the service life and daily maintenance of metallurgical cranes?\",\"answer\":\"With reinforced industrial structure and anti-high-temperature wear-resistant accessories, our metallurgical cranes have a longer service life than ordinary cranes. Daily maintenance is simple. We provide exclusive metallurgical equipment maintenance manuals and remote technical guidance for global users to reduce operating costs.\"}],\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"If you can not find the answer, contact us and let us know how we can help you.\",\"faq_contact_btn_text\":\"Contact Us\",\"faq_contact_btn_link\":\"\"},\"27\":{\"faq_title\":\"\",\"faq\":[],\"faq_contact_title\":\"\",\"faq_contact_desc\":\"\",\"faq_contact_btn_text\":\"\",\"faq_contact_btn_link\":\"\"},\"0\":{\"faq_title\":\"FAQ\",\"faq\":[{\"question\":\"问题1\",\"answer\":\"答案1\"},{\"question\":\"问题2\",\"answer\":\"答案2\"},{\"question\":\"问题3\",\"answer\":\"答案3\"},{\"question\":\"问题4\",\"answer\":\"答案4\"},{\"question\":\"问题5\",\"answer\":\"答案5\"}],\"faq_contact_title\":\"Can not Find Your Question?\",\"faq_contact_desc\":\"123123\",\"faq_contact_btn_text\":\"Contact Us\",\"faq_contact_btn_link\":\"\",\"faq_bg_img\":\"\"}}'),
('14', '1', 'smtp_setting', '{\"\\/admin\\/mailer\\/indexPost_html\":\"\",\"from_name\":\"Weihua Crane Inquiry\",\"from\":\"salea07@weihuahenancrane.com\",\"host\":\"mail.spacemail.com\",\"smtp_secure\":\"ssl\",\"port\":\"465\",\"username\":\"salea07@weihuahenancrane.com\",\"password\":\"WEIHUAhenan07.\"}');

-- --------------------------------------------------------
-- 表结构: `cmf_plugin`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_plugin`;
CREATE TABLE `cmf_plugin` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '插件类型;1:网站;8:微信',
  `has_admin` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否有后台管理,0:没有;1:有',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态;1:开启;0:禁用',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '插件安装时间',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '插件标识名,英文字母(惟一)',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件名称',
  `demo_url` varchar(50) NOT NULL DEFAULT '' COMMENT '演示地址，带协议',
  `hooks` varchar(255) NOT NULL DEFAULT '' COMMENT '实现的钩子;以“,”分隔',
  `author` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件作者',
  `author_url` varchar(50) NOT NULL DEFAULT '' COMMENT '作者网站链接',
  `version` varchar(20) NOT NULL DEFAULT '' COMMENT '插件版本号',
  `description` varchar(255) NOT NULL COMMENT '插件描述',
  `config` text COMMENT '插件配置',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='插件表';

-- 数据: `cmf_plugin`
INSERT INTO `cmf_plugin` (`id`, `type`, `has_admin`, `status`, `create_time`, `name`, `title`, `demo_url`, `hooks`, `author`, `author_url`, `version`, `description`, `config`) VALUES
('1', '1', '0', '1', '0', 'SwitchTheme', '前台模板切换', '', '', 'yingbo', '', '1.0.1', '前台模板切换', '{\"default_theme\":\"simpleboot3\",\"mobile_theme\":\"simpleboot3_mobile\"}');

-- --------------------------------------------------------
-- 表结构: `cmf_portal_category`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_portal_category`;
CREATE TABLE `cmf_portal_category` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '分类id',
  `parent_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '分类父id',
  `post_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT '分类文章数',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态,1:发布,0:不发布',
  `type` tinyint NOT NULL DEFAULT '1',
  `delete_time` int unsigned NOT NULL DEFAULT '0' COMMENT '删除时间',
  `list_order` float NOT NULL DEFAULT '10000' COMMENT '排序',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '分类描述',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT '分类层级关系路径',
  `seo_title` varchar(100) NOT NULL DEFAULT '',
  `seo_keywords` varchar(255) NOT NULL DEFAULT '',
  `seo_description` varchar(255) NOT NULL DEFAULT '',
  `list_tpl` varchar(50) NOT NULL DEFAULT '' COMMENT '分类列表模板',
  `one_tpl` varchar(50) NOT NULL DEFAULT '' COMMENT '分类文章页模板',
  `more` text COMMENT '扩展属性',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='portal应用 文章分类表';

-- 数据: `cmf_portal_category`
