DROP TABLE IF EXISTS `cmf_portal_tag`;
CREATE TABLE `cmf_portal_tag` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '分类id',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态,1:发布,0:不发布',
  `recommended` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否推荐;1:推荐;0:不推荐',
  `post_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT '标签文章数',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标签名称',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='portal应用 文章标签表';

-- --------------------------------------------------------
-- 表结构: `cmf_portal_tag_post`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_portal_tag_post`;
CREATE TABLE `cmf_portal_tag_post` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tag_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '标签 id',
  `post_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '文章 id',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态,1:发布;0:不发布',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `post_id` (`post_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='portal应用 标签文章对应表';

-- --------------------------------------------------------
-- 表结构: `cmf_product`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_product`;
CREATE TABLE `cmf_product` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL DEFAULT '0' COMMENT '分类id',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '产品标题',
  `alias` varchar(255) DEFAULT NULL COMMENT '产品别名（用于url美化）',
  `alias_name` text COMMENT '产品别名（逗号分割，用于匹配搜索）',
  `thumbnail` varchar(255) NOT NULL DEFAULT '' COMMENT '产品缩略图',
  `photos` text COMMENT '产品相册',
  `authentication_mark` text COMMENT '认证证书（证书配置列表，逗号分割）',
  `parameter` text COMMENT '产品参数',
  `lifting_capacity` varchar(255) DEFAULT NULL COMMENT '起重量',
  `lifting_height` varchar(255) NOT NULL DEFAULT '0.00' COMMENT '起重高度',
  `span` varchar(255) NOT NULL DEFAULT '0.00' COMMENT '跨度',
  `operating_voltage` varchar(255) DEFAULT NULL COMMENT '工作电压（列表，逗号分割）',
  `job_level` varchar(255) DEFAULT NULL COMMENT '工作等级（列表，逗号分割）',
  `industry` varchar(255) DEFAULT NULL COMMENT '应用行业',
  `file` varchar(255) DEFAULT NULL COMMENT '附件下载',
  `overview` text COMMENT '产品概述',
  `scenario` text COMMENT '应用场景',
  `certificate` text COMMENT '证书（图片标题列表）',
  `features` text COMMENT '特点特征',
  `customized` text COMMENT '定制服务',
  `custom_field` text COMMENT '自定义字段名',
  `custom_content` mediumtext COMMENT '自定义内容',
  `list_order` int NOT NULL DEFAULT '10000' COMMENT '排序',
  `is_recommended` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否推荐，0不推荐，1推荐',
  `create_time` int DEFAULT NULL COMMENT '创建时间',
  `update_time` int DEFAULT NULL COMMENT '更新时间',
  `delete_time` int DEFAULT NULL COMMENT '删除时间',
  `seo_title` varchar(255) DEFAULT NULL,
  `seo_keywords` varchar(255) DEFAULT NULL,
  `seo_description` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE,
  KEY `delete_time` (`delete_time`) USING BTREE,
  KEY `lifting_height` (`lifting_height`) USING BTREE,
  KEY `span` (`span`) USING BTREE,
  FULLTEXT KEY `content` (`title`,`overview`,`scenario`)
) ENGINE=InnoDB AUTO_INCREMENT=185 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='产品表';

-- 数据: `cmf_product`
INSERT INTO `cmf_product` (`id`, `category_id`, `title`, `alias`, `alias_name`, `thumbnail`, `photos`, `authentication_mark`, `parameter`, `lifting_capacity`, `lifting_height`, `span`, `operating_voltage`, `job_level`, `industry`, `file`, `overview`, `scenario`, `certificate`, `features`, `customized`, `custom_field`, `custom_content`, `list_order`, `is_recommended`, `create_time`, `update_time`, `delete_time`, `seo_title`, `seo_keywords`, `seo_description`) VALUES
('62', '28', 'LD Single Girder Overhead Crane', 'LD-Single-Girder-Overhead-Crane', 'testProduct,testProduct', 'portal/20260515/267bac9526e29e99a11748a3016dde5c.jpg', '[{\"url\":\"portal\\/20260424\\/36db4ee9507f74bfd4e7426e659be449.webp\",\"name\":\"图片-1.webp\"},{\"url\":\"portal\\/20260424\\/c6b6918493c5a97be6916574427e76d9.webp\",\"name\":\"图片-2.webp\"},{\"url\":\"portal\\/20260521\\/8ccd22032cab482b0a6328d748bba0ba.webp\",\"name\":\"Single Beam Bridge Crane LD Type (2).webp\"},{\"url\":\"portal\\/20260424\\/9230c6ed3e0a02c4666c41db0dd5dd75.webp\",\"name\":\"图片-4.webp\"},{\"url\":\"portal\\/20260424\\/0fcfd39c34a69cd8925a636618f61948.webp\",\"name\":\"图片-5.webp\"}]', '[{\"url\":\"admin\\/20241204\\/95d573c6faa18f16e9292dc67890b0d0.png\",\"name\":\"CCC\"},{\"url\":\"admin\\/20241204\\/b466eef6ed5d62d46e59c6ac814433cc.png\",\"name\":\"CE\"}]', '[]', '0.5-50t', '6, 9, 12m', '2.5-31.5', 'Three phrase; 380V, 50Hz', 'A3, A4, A5', 'LD Single Girder Overhead Crane is used in workshops, warehouses, and production lines for light to medium-duty material handling, offering efficient, space-saving, and cost-effective lifting solutions.', '[]', '&lt;div style=&quot;max-width: 1200px; margin: 0px auto; padding: 30px 20px; font-family: Arial, sans-serif; color: rgb(34, 34, 34); line-height: 1.8;&quot;&gt;
&lt;!-- Overview --&gt;&lt;div style=&quot;background: #f8f9fb; border: 1px solid #e5e7eb; border-radius: 12px; padding: 28px; margin-bottom: 24px;&quot;&gt;&lt;p style=&quot;margin: 0; font-size: 16px; color: #4b5563;&quot;&gt;The LD Single Girder Overhead Crane is a highly practical and cost-effective lifting solution widely used in industrial applications.
 It is typically combined with CD1 or MD1 electric hoists to form an efficient and reliable lifting system.&lt;/p&gt;&lt;/div&gt;
&lt;!-- Description --&gt;&lt;div style=&quot;font-size: 16px; color: #374151; margin-bottom: 24px;&quot;&gt;
&lt;p style=&quot;margin-bottom: 16px;&quot;&gt;The crane features a &lt;strong&gt;single girder structure&lt;/strong&gt; welded from high-quality steel, ensuring excellent strength, durability, and stability under load.
Its &lt;strong&gt;compact design and lightweight construction&lt;/strong&gt; make it particularly suitable for workshops and factories with limited space.&lt;/p&gt;
&lt;p style=&quot;margin-bottom: 16px;&quot;&gt;Compared with heavier crane systems, the LD crane is easier to install and maintain, significantly reducing installation time and maintenance costs.
In addition, its low wheel pressure places &lt;strong&gt;less demand on building structures&lt;/strong&gt;, helping to reduce plant construction costs.&lt;/p&gt;
&lt;/div&gt;
&lt;!-- Key Specifications --&gt;&lt;div style=&quot;display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; margin-bottom: 24px;&quot;&gt;
&lt;div style=&quot;background: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px; padding: 18px;&quot;&gt;
&lt;strong&gt;Lifting Capacity&lt;/strong&gt;&lt;br&gt;0.5 ton – 50 ton&lt;/div&gt;
&lt;div style=&quot;background: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px; padding: 18px;&quot;&gt;
&lt;strong&gt;Span Range&lt;/strong&gt;&lt;br&gt;2.5 m – 31.5 m&lt;/div&gt;
&lt;div style=&quot;background: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px; padding: 18px;&quot;&gt;
&lt;strong&gt;Working Temperature&lt;/strong&gt;&lt;br&gt;-20°C to +60°C&lt;/div&gt;
&lt;div style=&quot;background: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px; padding: 18px;&quot;&gt;
&lt;strong&gt;Control System&lt;/strong&gt;&lt;br&gt;Easy operation with precise lifting and movement control&lt;/div&gt;
&lt;/div&gt;
&lt;!-- Application --&gt;&lt;div style=&quot;background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 12px; padding: 22px; margin-bottom: 20px;&quot;&gt;
&lt;h3 style=&quot;margin: 0 0 12px; font-size: 24px; color: #111827;&quot;&gt;Application Areas&lt;/h3&gt;
&lt;ul style=&quot;margin: 0; padding-left: 20px; font-size: 16px; color: #374151; line-height: 1.9;&quot; class=&quot; list-paddingleft-2&quot;&gt;
&lt;li&gt;&lt;p&gt;Machinery manufacturing plants&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Assembly workshops and production lines&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Material yards and warehouses&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;General industrial lifting and material transfer&lt;/p&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;!-- Limitation / Safety --&gt;&lt;div style=&quot;background: #fff7f7; border: 1px solid #f3d6d6; border-left: 5px solid #e53935; border-radius: 12px; padding: 22px;&quot;&gt;
&lt;h3 style=&quot;margin: 0 0 12px; font-size: 22px; color: #b91c1c;&quot;&gt;Important Notes&lt;/h3&gt;
&lt;ul style=&quot;margin: 0; padding-left: 20px; font-size: 15px; color: #374151; line-height: 1.9;&quot; class=&quot; list-paddingleft-2&quot;&gt;
&lt;li&gt;&lt;p&gt;Not suitable for lifting hazardous materials such as molten metal, red-hot metal, or flammable goods&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Not recommended for environments with strong acidic or corrosive gases&lt;/p&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;', '&lt;div style=&quot;max-width: 1200px; margin: 0px auto; padding: 30px 15px; font-family: Arial, sans-serif;&quot;&gt;&lt;div style=&quot;display: flex; flex-wrap: wrap; gap: 24px; justify-content: center;&quot;&gt;
&lt;div style=&quot;flex: 1 1 500px; min-width: 300px; position: relative; min-height: 350px; overflow: hidden; background: url(\'/upload/default/20260424/58da1a3619a66cc5afd4a8828cb1ddb4.webp\') center/cover no-repeat; border-radius: 4px;&quot;&gt;
&lt;div style=&quot;position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.2), rgba(0,0,0,0.85));&quot;&gt;&lt;/div&gt;
&lt;div style=&quot;position: absolute; left: 25px; right: 25px; bottom: 25px; color: #fff;&quot;&gt;
&lt;h3 style=&quot;font-size: 24px; margin: 0 0 12px; font-weight: 700;&quot;&gt;Water Conservancy And Hydropower&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.5; margin: 0; font-weight: 400; opacity: 0.9;&quot;&gt;The dam-top gantry crane is installed on the top of a hydropower station dam. It is mainly used for gate lifting and material handling.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div style=&quot;flex: 1 1 500px; min-width: 300px; position: relative; min-height: 350px; overflow: hidden; background: url(\'/upload/default/20260424/53f8e47cb680e45180638afe05fd7034.webp\') center/cover no-repeat; border-radius: 4px;&quot;&gt;
&lt;div style=&quot;position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.2), rgba(0,0,0,0.85));&quot;&gt;&lt;/div&gt;
&lt;div style=&quot;position: absolute; left: 25px; right: 25px; bottom: 25px; color: #fff;&quot;&gt;
&lt;h3 style=&quot;font-size: 24px; margin: 0 0 12px; font-weight: 700;&quot;&gt;Wind Power Industry&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.5; margin: 0; font-weight: 400; opacity: 0.9;&quot;&gt;Weihua cranes are widely used in offshore wind power projects, especially for wind turbine installation and large component handling.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div style=&quot;flex: 1 1 500px; min-width: 300px; position: relative; min-height: 350px; overflow: hidden; background: url(\'/upload/default/20260424/7c19456728d86c85236af98f565ce874.webp\') center/cover no-repeat; border-radius: 4px;&quot;&gt;
&lt;div style=&quot;position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.2), rgba(0,0,0,0.85));&quot;&gt;&lt;/div&gt;
&lt;div style=&quot;position: absolute; left: 25px; right: 25px; bottom: 25px; color: #fff;&quot;&gt;
&lt;h3 style=&quot;font-size: 24px; margin: 0 0 12px; font-weight: 700;&quot;&gt;Shipyard Cranes&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.5; margin: 0; font-weight: 400; opacity: 0.9;&quot;&gt;Shipyard gantry cranes are designed for shipbuilding operations, including section lifting, turning, assembly, and launching.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div style=&quot;flex: 1 1 500px; min-width: 300px; position: relative; min-height: 350px; overflow: hidden; background: url(\'/upload/default/20260424/4a0f53f988ee6f3023455792bf0a34c6.webp\') center/cover no-repeat; border-radius: 4px;&quot;&gt;
&lt;div style=&quot;position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.2), rgba(0,0,0,0.85));&quot;&gt;&lt;/div&gt;
&lt;div style=&quot;position: absolute; left: 25px; right: 25px; bottom: 25px; color: #fff;&quot;&gt;
&lt;h3 style=&quot;font-size: 24px; margin: 0 0 12px; font-weight: 700;&quot;&gt;Steel Mill Cranes&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.5; margin: 0; font-weight: 400; opacity: 0.9;&quot;&gt;Weihua metallurgical cranes are used in steel mills covering lifting needs from smelting to finished product handling.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;', '[]', '&lt;div style=&quot;max-width: 1200px; margin: 0px auto; padding: 20px 10px; font-family: Arial, sans-serif; color: rgb(17, 17, 17);&quot;&gt;&lt;div style=&quot;display: flex; flex-wrap: wrap; gap: 20px; justify-content: center;&quot;&gt;
&lt;div style=&quot;flex: 1 1 450px; min-width: 300px; background: #f3f3f3; padding: 40px 30px; text-align: center; box-sizing: border-box;&quot;&gt;
&lt;img src=&quot;default/20260424/cd61e7f2b73f4a62799b48c3bc88092f.png&quot; alt=&quot;Brand Reputation&quot; style=&quot;width: 64px; height: 64px; object-fit: contain; margin-bottom: 18px;&quot;&gt;&lt;h3 style=&quot;font-size: 22px; margin: 0 0 14px; font-weight: 700;&quot;&gt;Brand Reputation&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.65; margin: 0;&quot;&gt;Weihua Cranes ranks among the top sellers in China\'s crane industry, boasting high brand awareness and market share. Its products are widely used in numerous national key projects.&lt;/p&gt;
&lt;/div&gt;
&lt;div style=&quot;flex: 1 1 450px; min-width: 300px; background: #f3f3f3; padding: 40px 30px; text-align: center; box-sizing: border-box;&quot;&gt;
&lt;img src=&quot;default/20260424/467d4a2a355a54ca0f34d80317b858ba.png&quot; alt=&quot;Full Service&quot; style=&quot;width: 64px; height: 64px; object-fit: contain; margin-bottom: 18px;&quot;&gt;&lt;h3 style=&quot;font-size: 22px; margin: 0 0 14px; font-weight: 700;&quot;&gt;Full Service&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.65; margin: 0;&quot;&gt;Weihua provides a one-stop service, encompassing consultation and planning, solution design, installation, and localized technical support worldwide.&lt;/p&gt;
&lt;/div&gt;
&lt;div style=&quot;flex: 1 1 450px; min-width: 300px; background: #f3f3f3; padding: 40px 30px; text-align: center; box-sizing: border-box;&quot;&gt;
&lt;img src=&quot;default/20260424/afcfb65440a841b405fc0f9ce44b8ae1.png&quot; alt=&quot;Excellent Product Quality&quot; style=&quot;width: 64px; height: 64px; object-fit: contain; margin-bottom: 18px;&quot;&gt;&lt;h3 style=&quot;font-size: 22px; margin: 0 0 14px; font-weight: 700;&quot;&gt;Excellent Product Quality&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.65; margin: 0;&quot;&gt;Weihua Crane employs automated production lines and precision machining equipment. Key components are sourced from well-known domestic and international brands.&lt;/p&gt;
&lt;/div&gt;
&lt;div style=&quot;flex: 1 1 450px; min-width: 300px; background: #f3f3f3; padding: 40px 30px; text-align: center; box-sizing: border-box;&quot;&gt;
&lt;img src=&quot;default/20260424/6f13f30218a6f6354b3e729b620a1090.png&quot; alt=&quot;High Safety&quot; style=&quot;width: 64px; height: 64px; object-fit: contain; margin-bottom: 18px;&quot;&gt;&lt;h3 style=&quot;font-size: 22px; margin: 0 0 14px; font-weight: 700;&quot;&gt;High Safety&lt;/h3&gt;
&lt;p style=&quot;font-size: 15px; line-height: 1.65; margin: 0;&quot;&gt;Weihua Lifting strictly adheres to international standards such as GB and FEM. Key structures adopt high safety factors to ensure precise operation.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;', '&lt;div style=&quot;max-width: 1200px; margin: 0px auto; padding: 30px 20px; font-family: Arial, sans-serif; color: rgb(34, 34, 34); line-height: 1.8;&quot;&gt;
&lt;!-- Title --&gt;&lt;div style=&quot;background: #f8f9fb; border: 1px solid #e5e7eb; border-radius: 12px; padding: 28px; margin-bottom: 24px;&quot;&gt;
&lt;h2 style=&quot;margin: 0 0 12px; font-size: 28px; color: #111827;&quot;&gt;Customized LD Single Girder Overhead Crane Solutions&lt;/h2&gt;
&lt;p style=&quot;margin: 0; font-size: 16px; color: #4b5563;&quot;&gt;Weihua Crane provides fully customized LD Single Girder Overhead Crane solutions for light to medium-duty industrial applications, offering high efficiency, cost-effectiveness, and reliable performance.&lt;/p&gt;
&lt;/div&gt;
&lt;!-- Description --&gt;&lt;div style=&quot;font-size: 16px; color: #374151; margin-bottom: 24px;&quot;&gt;&lt;p style=&quot;margin-bottom: 16px;&quot;&gt;Key parameters such as &lt;strong&gt;lifting capacity, span, lifting height, and installation space&lt;/strong&gt; can be flexibly adjusted to suit different workshop layouts, ensuring optimal material handling efficiency and space utilization.&lt;/p&gt;&lt;/div&gt;
&lt;!-- Configurations --&gt;&lt;div style=&quot;background: #ffffff; border: 1px solid #e5e7eb; border-radius: 12px; padding: 22px; margin-bottom: 20px;&quot;&gt;
&lt;h3 style=&quot;margin: 0 0 12px; font-size: 22px; color: #111827;&quot;&gt;Optional Configurations&lt;/h3&gt;
&lt;ul style=&quot;margin: 0; padding-left: 20px; font-size: 16px; color: #374151; line-height: 1.9;&quot; class=&quot; list-paddingleft-2&quot;&gt;
&lt;li&gt;&lt;p&gt;Remote control or pendant control system&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Electric hoist options&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Frequency conversion for smooth and stable operation&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Overload protection and limit switch safety devices&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Customized design for low headroom and compact spaces&lt;/p&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
