-- --------------------------------------------------------
-- 表结构: `cmf_product_category`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_product_category`;
CREATE TABLE `cmf_product_category` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '分类名称',
  `alias` varchar(255) DEFAULT NULL COMMENT '分类别名（用于url美化）',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父级分类id',
  `thumbnail` varchar(255) NOT NULL DEFAULT '' COMMENT '缩略图',
  `recommend` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `list_order` int NOT NULL DEFAULT '10000' COMMENT '排序',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `delete_time` int DEFAULT NULL COMMENT '删除时间',
  `seo_title` varchar(255) DEFAULT NULL,
  `seo_keywords` varchar(255) DEFAULT NULL,
  `seo_description` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `delete_time` (`delete_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='产品分类表';

-- 数据: `cmf_product_category`
INSERT INTO `cmf_product_category` (`id`, `name`, `alias`, `parent_id`, `thumbnail`, `recommend`, `list_order`, `create_time`, `delete_time`, `seo_title`, `seo_keywords`, `seo_description`) VALUES
('19', 'Gantry Crane', 'GantryCrane', '0', 'admin/20260526/2194b4d907667be71b7d9b03b757c8ec.webp', '1', '2', '1774798045', NULL, 'Heavy Duty Gantry Crane | Container Gantry Crane for Port Yard', 'gantry crane, rail mounted gantry crane, RMG crane, portable gantry crane, mobile gantry crane, container gantry crane, single girder gantry crane, double girder gantry crane, outdoor gantry crane, port gantry crane, yard gantry crane', 'High-quality gantry cranes supplied by Henan Weihua. Customizable lifting capacity, span and lifting height.Widely applied in ports, freight yards, construction sites and logistics parks, stable operation and long service life.'),
('22', 'Metallurgy Crane', 'MetallurgyCrane', '0', 'admin/20260526/2194b4d907667be71b7d9b03b757c8ec.webp', '0', '5', '1774798107', NULL, 'Metallurgy Crane, High Temp Resistant Lifting Equipment for Steel Mill', 'metallurgy crane,metallurgical crane,steel mill crane,ladle crane', 'Reliable lifting crane dedicated to metallurgy industry. Adapt well to frequent heavy duty work, practical design reduces daily maintenance trouble.'),
('23', 'Port Crane', 'PortCrane', '0', 'admin/20260526/2194b4d907667be71b7d9b03b757c8ec.webp', '1', '6', '1774798127', NULL, 'Custom Port Crane Stable Operation for Seaport Transportation Work', 'Port Crane,Harbor Crane,Dock Crane,Container Port Crane,Heavy Duty Port Crane,Seaport Cargo Handling Crane,Port Gantry Crane', 'Professional port crane with flexible customized specifications. Safe and efficient operation meets diverse cargo transportation demands in coastal ports.'),
('25', 'Jib Crane', 'jibcrane', '0', 'admin/20260526/2194b4d907667be71b7d9b03b757c8ec.webp', '1', '8', '1774798159', NULL, 'Light Crane Compact Lightweight Lifting Equipment', 'Light Crane,Jib Crane,Suspension Crane', 'Practical light lifting crane saves floor space, moves freely to finish routine material hoisting work with stable performance.'),
('27', 'Crane Parts', 'CraneParts', '0', 'admin/20260526/2194b4d907667be71b7d9b03b757c8ec.webp', '0', '10', '1774798197', NULL, '', '', ''),
('28', 'Overhead Crane', 'overhead-crane', '0', 'admin/20260526/2194b4d907667be71b7d9b03b757c8ec.webp', '1', '1', '1777020185', NULL, 'Industrial Overhead Travelling Crane | Electric Hoist Bridge Crane Manufacturer', 'overhead crane, bridge crane, overhead travelling crane, single girder overhead crane, double girder overhead crane, electric hoist overhead crane, industrial bridge crane, workshop overhead crane, warehouse lifting crane, Weihua overhead crane', 'Weihua supplies high quality single girder and double girder overhead cranes with stable performance, customized span and lifting capacity. '),
('30', 'Electric Hoist', 'Electric-Hoist', '0', 'admin/20260526/2194b4d907667be71b7d9b03b757c8ec.webp', '1', '9', '1777428627', NULL, '', '', '');

-- --------------------------------------------------------
-- 表结构: `cmf_product_profession`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_product_profession`;
CREATE TABLE `cmf_product_profession` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL COMMENT '产品id',
  `tag_id` int NOT NULL COMMENT '行业标签id',
  `create_time` int DEFAULT NULL,
  `delete_time` int DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='产品行业标签中间表';

-- --------------------------------------------------------
-- 表结构: `cmf_profession`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_profession`;
CREATE TABLE `cmf_profession` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '行业标签',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用，0禁用',
  `create_time` int DEFAULT NULL COMMENT '创建时间',
  `delete_time` int DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='产品行业标签表';

-- --------------------------------------------------------
-- 表结构: `cmf_recycle_bin`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `cmf_recycle_bin`;
CREATE TABLE `cmf_recycle_bin` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `object_id` int DEFAULT '0' COMMENT '删除内容 id',
  `create_time` int unsigned DEFAULT '0' COMMENT '创建时间',
  `table_name` varchar(60) DEFAULT '' COMMENT '删除内容所在表名',
  `name` varchar(255) DEFAULT '' COMMENT '删除内容名称',
  `user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT=' 回收站';

